
// Lista de pacientes
let pessoas = [];

// Contador de códigos
let proximoId = 1;

// Chave do armazenamento
const CHAVE_PESSOAS = "pessoas";

// Referências do HTML
const formPessoa = document.getElementById("form-pessoa");
const inputNome = document.getElementById("nome");
const inputIdade = document.getElementById("idade");
const inputAltura = document.getElementById("altura");
const inputPeso = document.getElementById("peso");
const mensagemDeErro = document.getElementById("erro");
const tabelaPessoas = document.getElementById("tabela-pessoas");
const mensagemVazia = document.getElementById("vazio");

// Formatação de números
function formatar(valor, casas) {
    return valor.toFixed(casas).replace(".", ",");
    }

    // Cálculo do IMC
    function calcularIMC(peso, altura) {
        return peso / (altura * altura);
        }

        // Classificação do IMC
        function classificarIMC(imc) {

            if (imc < 18.5) {
                    return {
                                texto: "Baixo peso",
                                            classe: "baixo-peso"
                                                    };
                                                        }

                                                            if (imc < 25) {
                                                                    return {
                                                                                texto: "Normal",
                                                                                            classe: "normal"
                                                                                                    };
                                                                                                        }

                                                                                                            if (imc < 30) {
                                                                                                                    return {
                                                                                                                                texto: "Sobrepeso",
                                                                                                                                            classe: "atencao"
                                                                                                                                                    };
                                                                                                                                                        }

                                                                                                                                                            if (imc < 35) {
                                                                                                                                                                    return {
                                                                                                                                                                                texto: "Obesidade I",
                                                                                                                                                                                            classe: "obesidade"
                                                                                                                                                                                                    };
                                                                                                                                                                                                        }

                                                                                                                                                                                                            if (imc < 40) {
                                                                                                                                                                                                                    return {
                                                                                                                                                                                                                                texto: "Obesidade II",
                                                                                                                                                                                                                                            classe: "obesidade"
                                                                                                                                                                                                                                                    };
                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                            return {
                                                                                                                                                                                                                                                                    texto: "Obesidade III",
                                                                                                                                                                                                                                                                            classe: "obesidade"
                                                                                                                                                                                                                                                                                };
                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                // Criação de uma célula
                                                                                                                                                                                                                                                                                function criarCelula(conteudo) {
                                                                                                                                                                                                                                                                                    const td = document.createElement("td");
                                                                                                                                                                                                                                                                                        td.textContent = conteudo;
                                                                                                                                                                                                                                                                                            return td;
                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                            // Criação da linha da tabela
                                                                                                                                                                                                                                                                                            function criarLinha(pessoa) {

                                                                                                                                                                                                                                                                                                const tr = document.createElement("tr");

                                                                                                                                                                                                                                                                                                    const imc = calcularIMC(pessoa.peso, pessoa.altura);
                                                                                                                                                                                                                                                                                                        const classificacao = classificarIMC(imc);

                                                                                                                                                                                                                                                                                                            tr.appendChild(criarCelula(pessoa.id));
                                                                                                                                                                                                                                                                                                                tr.appendChild(criarCelula(pessoa.nome));
                                                                                                                                                                                                                                                                                                                    tr.appendChild(criarCelula(pessoa.idade + " anos"));
                                                                                                                                                                                                                                                                                                                        tr.appendChild(criarCelula(formatar(pessoa.altura, 2) + " m"));
                                                                                                                                                                                                                                                                                                                            tr.appendChild(criarCelula(formatar(pessoa.peso, 1) + " kg"));
                                                                                                                                                                                                                                                                                                                                tr.appendChild(criarCelula(formatar(imc, 1)));

                                                                                                                                                                                                                                                                                                                                    // Coluna da classificação
                                                                                                                                                                                                                                                                                                                                        const tdClassificacao = document.createElement("td");

                                                                                                                                                                                                                                                                                                                                            const selo = document.createElement("span");

                                                                                                                                                                                                                                                                                                                                                selo.classList.add("selo");
                                                                                                                                                                                                                                                                                                                                                    selo.classList.add(classificacao.classe);

                                                                                                                                                                                                                                                                                                                                                        selo.textContent = classificacao.texto;

                                                                                                                                                                                                                                                                                                                                                            tdClassificacao.appendChild(selo);
                                                                                                                                                                                                                                                                                                                                                                tr.appendChild(tdClassificacao);

                                                                                                                                                                                                                                                                                                                                                                    // Botão de apagar
                                                                                                                                                                                                                                                                                                                                                                        const tdAcao = document.createElement("td");
                                                                                                                                                                                                                                                                                                                                                                            const botaoApagar = document.createElement("button");

                                                                                                                                                                                                                                                                                                                                                                                botaoApagar.textContent = "Apagar";
                                                                                                                                                                                                                                                                                                                                                                                    botaoApagar.classList.add("btn-apagar");

                                                                                                                                                                                                                                                                                                                                                                                        botaoApagar.addEventListener("click", function () {
                                                                                                                                                                                                                                                                                                                                                                                                apagarPessoa(pessoa.id);
                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                        tdAcao.appendChild(botaoApagar);
                                                                                                                                                                                                                                                                                                                                                                                                            tr.appendChild(tdAcao);

                                                                                                                                                                                                                                                                                                                                                                                                                return tr;
                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                // Renderização da tabela
                                                                                                                                                                                                                                                                                                                                                                                                                function render() {

                                                                                                                                                                                                                                                                                                                                                                                                                    tabelaPessoas.innerHTML = "";

                                                                                                                                                                                                                                                                                                                                                                                                                        pessoas.forEach(function (pessoa) {
                                                                                                                                                                                                                                                                                                                                                                                                                                const linha = criarLinha(pessoa);
                                                                                                                                                                                                                                                                                                                                                                                                                                        tabelaPessoas.appendChild(linha);
                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                mensagemVazia.hidden = pessoas.length !== 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                // Leitura dos dados do formulário
                                                                                                                                                                                                                                                                                                                                                                                                                                                function lerFormulario() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                    return {
                                                                                                                                                                                                                                                                                                                                                                                                                                                            nome: inputNome.value.trim(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    idade: Number(inputIdade.value),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            altura: Number(inputAltura.value),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    peso: Number(inputPeso.value)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Validação dos dados
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function validarDados(dados) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (dados.nome.length < 2) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return "Informe o nome com no mínimo duas letras.";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!Number.isInteger(dados.idade) ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    dados.idade < 1 || dados.idade > 120) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return "A idade deve ser um número inteiro entre 1 e 120.";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!Number.isFinite(dados.altura) ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            dados.altura < 0.5 || dados.altura > 2.5) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return "A altura deve estar entre 0,5 m e 2,5 m.";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!Number.isFinite(dados.peso) ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    dados.peso < 2 || dados.peso > 500) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return "O peso deve estar entre 2 kg e 500 kg.";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Exibição de erro
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function mostrarErro(mensagem) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        mensagemDeErro.textContent = mensagem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            mensagemDeErro.hidden = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // Limpeza de erro
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function limparErro() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                mensagemDeErro.textContent = "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mensagemDeErro.hidden = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Adicionar pessoa
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function adicionarPessoa(dados) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const pessoa = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                id: proximoId,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        nome: dados.nome,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                idade: dados.idade,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        altura: dados.altura,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                peso: dados.peso
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        pessoas.push(pessoa);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            proximoId++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // Salvar no localStorage
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function salvar() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                localStorage.setItem(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        CHAVE_PESSOAS,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                JSON.stringify(pessoas)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Carregar pessoas salvas
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function carregarPessoas() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const dados = localStorage.getItem(CHAVE_PESSOAS);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (dados === null) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return [];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            try {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const lista = JSON.parse(dados);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (Array.isArray(lista)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return lista;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return [];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } catch (erro) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    console.error("Erro ao carregar os pacientes:", erro);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return [];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Ajustar contador de códigos
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function ajustarContador() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    let maior = 0;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        pessoas.forEach(function (pessoa) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (Number.isInteger(pessoa.id) && pessoa.id > maior) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            maior = pessoa.id;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            proximoId = maior + 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // Apagar pessoa
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function apagarPessoa(id) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                pessoas = pessoas.filter(function (pessoa) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return pessoa.id !== id;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                salvar();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    render();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Evento de envio do formulário
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    formPessoa.addEventListener("submit", function (e) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        e.preventDefault();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const dados = lerFormulario();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const erro = validarDados(dados);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (erro !== "") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            mostrarErro(erro);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            limparErro();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                adicionarPessoa(dados);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    salvar();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        render();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            formPessoa.reset();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                inputNome.focus();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Inicialização da aplicação
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                pessoas = carregarPessoas();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ajustarContador();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                render();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                